    priority_queue(InputIterator first, InputIterator last, const Compare& compare, Container&& cont,
        const Alloc& a);
    Effects: Initializes c with std::move(cont) as the first argument and a as the second argument,
    and initializes comp with compare; calls c.insert(c.end(), first, last); and finally calls make_-
    heap(c.begin(), c.end(), comp).

template<container-compatible-range<T> R, class Alloc>
    priority_queue(from_range_t, R&& rg, const Compare& compare, const Alloc& a);
    Effects: Initializes comp with compare and c with ranges::to<Container>(std::forward<R>(rg),
        a); calls make_heap(c.begin(), c.end(), comp).

template<container-compatible-range<T> R, class Alloc>
    priority_queue(from_range_t, R&& rg, const Alloc& a);
    Effects: Initializes c with ranges::to<Container>(std::forward<R>(rg), a); calls make_heap(c.
        begin(), c.end(), comp).

24.6.7.4 Members
void push(const value_type& x);
    Effects: As if by:
        c.push_back(x);
        push_heap(c.begin(), c.end(), comp);

void push(value_type&& x);
    Effects: As if by:
        c.push_back(std::move(x));
        push_heap(c.begin(), c.end(), comp);

template<container-compatible-range<T> R>
    void push_range(R&& rg);
    Effects: Inserts all elements of rg in c via c.append_range(std::forward<R>(rg)) if that is a valid
    expression, or ranges::copy(rg, back_inserter(c)) otherwise. Then restores the heap property as
    if by make_heap(c.begin(), c.end(), comp).
    Postconditions: is_heap(c.begin(), c.end(), comp) is true.

template<class... Args> void emplace(Args&&... args);
    Effects: As if by:
        c.emplace_back(std::forward<Args>(args)...);
        push_heap(c.begin(), c.end(), comp);

void pop();
    Effects: As if by:
        pop_heap(c.begin(), c.end(), comp);
        c.pop_back();

24.6.7.5 Specialized algorithms
template<class T, class Container, class Compare>
    void swap(priority_queue<T, Container, Compare>& x,
        priority_queue<T, Container, Compare>& y) noexcept(noexcept(x.swap(y)));
    Constraints: is_swappable_v<Container> is true and is_swappable_v<Compare> is true.
    Effects: As if by x.swap(y).

24.6.8 Class template stack
24.6.8.1 General
Any sequence container supporting operations back(), push_back() and pop_back() can be used to instan-
tiate stack. In particular, vector (24.3.11), list (24.3.10) and deque (24.3.8) can be used.
